/* apple2e_chips.c - the chips of the Apple IIe board (820-0064-B, unenhanced) that the other machines do not have.
 *
 * The three custom chips are behavioural models of the real thing, not of the pins' function in the abstract:
 *  - the MMU (344-0010, UE4) and the IOU (344-0020, UE5) are generated by tools/vhdl2c.py from frozen-signal's VHDL
 *    re-implementation (CC0, https://github.com/frozen-signal/Apple_IIe_MMU_IOU), which is drawn from Apple's own schematics
 *    of the two chips and runs on real IIe boards: apple2e_mmu.inc and apple2e_iou.inc. Each chip is run as VHDL runs it, in
 *    delta cycles over its flattened signals, once for every step of the board in which one of its inputs changed.
 *  - the timing PAL (the "HAL", 341-0170, UD1) is the seven registered equations that were read from a real chip's JEDEC map,
 *    as frozen-signal's Apple_IIe_TIMING_HAL (CC0) has them: all outputs change on the rising edge of the 14M clock.
 * The ROMs are 28 pin 2764s (the two 8K firmware ROMs), the 2732 video ROM and the 2716 keyboard ROM; the keyboard encoder
 * (3600 PRO) is a part that holds the key the machine has typed.
 * 74LS109 and 74LS374 are here because no other machine has them. */
#include "parts.h"
#include <string.h>

/* ------------------------------------------------------------------------ */
/* MMU                                                                       */
/* ------------------------------------------------------------------------ */
#include "apple2e_mmu.inc"

typedef struct { mmu_t m; uint32_t in[7]; uint8_t valid; } a2e_mmu_t;
static const int mmu_apin[16] = { 2, 40, 39, 38, 37, 36, 35, 34, 33, 32, 31, 30, 29, 28, 27, 26 };   /* A0 .. A15 */

static void mmu_eval(sim_t *s, part_t *p) {
    const a2e_mmu_t *t = p->state;
    const mmu_t *m = &t->m;
    for (int i = 0; i < 8; i++)
        pin_out(s, p, 6 + i, (m->z[MMU_ORA] >> i) & 1 ? DRV_Z : DRV_BIT((m->c[MMU_ORA] >> i) & 1));
    pin_out(s, p, 17, DRV_BIT(m->c[MMU_EN80_N]));
    pin_out(s, p, 18, DRV_BIT(m->c[MMU_KBD_N]));
    pin_out(s, p, 19, DRV_BIT(m->c[MMU_ROMEN2_N]));
    pin_out(s, p, 20, DRV_BIT(m->c[MMU_ROMEN1_N]));
    pin_out(s, p, 21, m->z[MMU_MD7] ? DRV_Z : DRV_BIT(m->c[MMU_MD7]));
    pin_out(s, p, 22, DRV_BIT(m->c[MMU_R_W_N_245]));
    pin_out(s, p, 23, DRV_BIT(m->c[MMU_CASEN_N]));
    pin_out(s, p, 24, DRV_BIT(m->c[MMU_CXXXOUT]));
}
static void mmu_commit(sim_t *s, part_t *p) {
    a2e_mmu_t *t = p->state;
    uint32_t in[7];
    in[0] = part_read_bus(s, p, mmu_apin, 16);
    in[1] = (uint32_t)pin_in(s, p, 3);      /* PHI0 */
    in[2] = (uint32_t)pin_in(s, p, 4);      /* Q3 */
    in[3] = (uint32_t)pin_in(s, p, 5);      /* PRAS' */
    in[4] = (uint32_t)pin_in(s, p, 14);     /* R/W' */
    in[5] = (uint32_t)pin_in(s, p, 15);     /* INH' */
    in[6] = (uint32_t)pin_in(s, p, 16);     /* DMA' */
    if (t->valid && !memcmp(in, t->in, sizeof(in))) return;
    memcpy(t->in, in, sizeof(in));
    t->valid = 1;
    mmu_t *m = &t->m;
    m->c[MMU_A] = in[0]; m->c[MMU_PHI_0] = in[1]; m->c[MMU_Q3] = in[2]; m->c[MMU_PRAS_N] = in[3];
    m->c[MMU_R_W_N] = in[4]; m->c[MMU_INH_N] = in[5]; m->c[MMU_DMA_N] = in[6];
    mmu_run(m);
    sim_mark_dirty(s, (int)(p - s->parts));
}
static void mmu_reset_part(sim_t *s, part_t *p) {
    (void)s;
    a2e_mmu_t *t = p->state;
    memset(t, 0, sizeof(*t));
    mmu_reset(&t->m);
}
const part_type_t PT_A2E_MMU = { "MMU 344-0010",
    "GND:P A0:m PHI0:m Q3:m /PRAS:m RA0:O RA1:O RA2:O RA3:O RA4:O RA5:O RA6:O RA7:O R/W:m /INH:m /DMA:m /EN80:O /KBD:O "
    "/ROMEN2:O /ROMEN1:O MD7:O RW245:O /CASEN:O CXXX:O VCC:P A15:m A14:m A13:m A12:m A11:m A10:m A9:m A8:m A7:m A6:m "
    "A5:m A4:m A3:m A2:m A1:m",
    mmu_eval, mmu_commit, mmu_reset_part, sizeof(a2e_mmu_t), TECH_NMOS };

/* ------------------------------------------------------------------------ */
/* IOU                                                                       */
/* ------------------------------------------------------------------------ */
#include "apple2e_iou.inc"

typedef struct { iou_t m; uint32_t in[11]; uint8_t valid; } a2e_iou_t;
static const int iou_ra_pin[8] = { 17, 18, 19, 20, 21, 22, 23, 24 };
static const int iou_ra_sig[8] = { IOU_ORA0, IOU_ORA1, IOU_ORA2, IOU_ORA3, IOU_ORA4, IOU_ORA5, IOU_ORA6, IOU_ORA7 };

static void iou_eval(sim_t *s, part_t *p) {
    const a2e_iou_t *t = p->state;
    const iou_t *m = &t->m;
    for (int i = 0; i < 8; i++)
        pin_out(s, p, iou_ra_pin[i], m->z[iou_ra_sig[i]] ? DRV_Z : DRV_BIT(m->c[iou_ra_sig[i]]));
    pin_out(s, p, 15, m->z[IOU_RESET_N] ? DRV_PULLUP : DRV_LO);       /* open collector: the chip has the pull-up inside */
    pin_out(s, p, 2, DRV_BIT(m->c[IOU_LGR_TXT_N]));
    pin_out(s, p, 3, DRV_BIT(m->c[IOU_SEGA]));
    pin_out(s, p, 4, DRV_BIT(m->c[IOU_SEGB]));
    pin_out(s, p, 5, DRV_BIT(m->c[IOU_SEGC]));
    pin_out(s, p, 6, DRV_BIT(m->c[IOU_S_80COL_N]));
    pin_out(s, p, 7, DRV_BIT(m->c[IOU_CASSO]));
    pin_out(s, p, 8, DRV_BIT(m->c[IOU_SPKR]));
    pin_out(s, p, 9, m->z[IOU_MD7] ? DRV_Z : DRV_BIT(m->c[IOU_MD7]));
    pin_out(s, p, 10, DRV_BIT(m->c[IOU_AN0]));
    pin_out(s, p, 11, DRV_BIT(m->c[IOU_AN1]));
    pin_out(s, p, 12, DRV_BIT(m->c[IOU_AN2]));
    pin_out(s, p, 13, DRV_BIT(m->c[IOU_AN3]));
    pin_out(s, p, 35, DRV_BIT(m->c[IOU_RA9_N]));
    pin_out(s, p, 36, DRV_BIT(m->c[IOU_RA10_N]));
    pin_out(s, p, 37, DRV_BIT(m->c[IOU_CLRGAT_N]));
    pin_out(s, p, 38, DRV_BIT(m->c[IOU_WNDW_N]));
    pin_out(s, p, 39, DRV_BIT(m->c[IOU_SYNC_N]));
    pin_out(s, p, 40, DRV_BIT(m->c[IOU_H0]));
}
static void iou_commit(sim_t *s, part_t *p) {
    a2e_iou_t *t = p->state;
    uint32_t in[11];
    in[0] = (uint32_t)pin_in(s, p, 26);     /* PHI0 */
    in[1] = (uint32_t)pin_in(s, p, 27);     /* Q3 */
    in[2] = (uint32_t)pin_in(s, p, 25);     /* PRAS' */
    in[3] = (uint32_t)pin_in(s, p, 14);     /* R/W' */
    in[4] = (uint32_t)pin_in(s, p, 30);     /* C0XX' */
    in[5] = (uint32_t)pin_in(s, p, 34);     /* VID6 */
    in[6] = (uint32_t)pin_in(s, p, 33);     /* VID7 */
    in[7] = (uint32_t)pin_in(s, p, 29);     /* A6 */
    in[8] = (uint32_t)pin_in(s, p, 32);     /* KSTRB */
    in[9] = (uint32_t)pin_in(s, p, 31);     /* AKD */
    in[10] = (uint32_t)pin_in(s, p, 15);    /* RESET' (also an output: the IOU holds it low at power on) */
    if (t->valid && !memcmp(in, t->in, sizeof(in))) return;
    memcpy(t->in, in, sizeof(in));
    t->valid = 1;
    iou_t *m = &t->m;
    m->c[IOU_PHI_0] = in[0]; m->c[IOU_Q3] = in[1]; m->c[IOU_PRAS_N] = in[2]; m->c[IOU_R_W_N] = in[3];
    m->c[IOU_C0XX_N] = in[4]; m->c[IOU_VID6] = in[5]; m->c[IOU_VID7] = in[6]; m->c[IOU_A6] = in[7];
    m->c[IOU_IKSTRB] = in[8]; m->c[IOU_IAKD] = in[9]; m->c[IOU_RESET_N] = in[10];
    iou_run(m);
    sim_mark_dirty(s, (int)(p - s->parts));
}
static void iou_reset_part(sim_t *s, part_t *p) {
    (void)s;
    a2e_iou_t *t = p->state;
    memset(t, 0, sizeof(*t));
    iou_reset(&t->m);
}
const part_type_t PT_A2E_IOU = { "IOU 344-0020",
    "GND:P GR:O SEGA:O SEGB:O VC:O /80VID:O CASSO:O SPKR:O MD7:O AN0:O AN1:O AN2:O AN3:O R/W:m /RESET:X NC:O RA0:O RA1:O RA2:O "
    "RA3:O RA4:O RA5:O RA6:O RA7:O /PRAS:m PHI0:m Q3:m VCC:P A6:m /C0XX:m AKD:m KSTRB:m VID7:m VID6:m /RA9:O /RA10:O "
    "/CLRGAT:O /WNDW:O /SYNC:O H0:O",
    iou_eval, iou_commit, iou_reset_part, sizeof(a2e_iou_t), TECH_NMOS };

/* ------------------------------------------------------------------------ */
/* The timing PAL                                                            */
/* ------------------------------------------------------------------------ */

/* 16R8: every output is a register on the rising edge of 14M (pin 1); pin 11 (/ENTMG) enables the outputs. The equations are
 * the ones read from a real chip. A set-up of all zeros is a state the machine runs out of in about a cycle. */
typedef struct { uint8_t ras, ax, ph0, q3, cas, vid7m, ldps, ck; } hal_t;
static void hal_eval(sim_t *s, part_t *p) {
    const hal_t *h = p->state;
    bool on = !pin_in(s, p, 11);
    pin_out(s, p, 12, on ? DRV_BIT(h->ldps) : DRV_Z);
    pin_out(s, p, 13, on ? DRV_BIT(h->vid7m) : DRV_Z);
    pin_out(s, p, 14, on ? DRV_BIT(!h->ph0) : DRV_Z);
    pin_out(s, p, 15, on ? DRV_BIT(h->ph0) : DRV_Z);
    pin_out(s, p, 16, on ? DRV_BIT(h->q3) : DRV_Z);
    pin_out(s, p, 17, on ? DRV_BIT(h->cas) : DRV_Z);
    pin_out(s, p, 19, on ? DRV_BIT(h->ras) : DRV_Z);
}
static void hal_commit(sim_t *s, part_t *p) {
    hal_t *h = p->state;
    int ck = pin_in(s, p, 1);
    if (ck && !h->ck) {
        int m7 = pin_in(s, p, 2), cref = pin_in(s, p, 3), h0 = pin_in(s, p, 4), vid7 = pin_in(s, p, 5), segb = pin_in(s, p, 6);
        int gr_n = pin_in(s, p, 7), casen_n = pin_in(s, p, 8), col80_n = pin_in(s, p, 9);
        int ras = h->ras, ax = h->ax, ph = h->ph0, q3 = h->q3, cas = h->cas, v = h->vid7m;
        hal_t n = *h;
        n.ras = !(q3 || (m7 && !ras && !ph) || (!m7 && !ax && ph) || (m7 && cref && ax && h0 && ph) || (!m7 && !cref && ax && h0 && ph));
        n.ax = !(!ras && q3);
        n.ph0 = !((ras && !q3 && ph) || (q3 && !ph) || (!ras && !ph));
        n.q3 = !((!m7 && !ax && !ph) || (!ras && !q3) || (m7 && !ax && ph));
        n.cas = !((!ras && !ax && cas && !ph) || (!ras && !ax && cas && ph && !casen_n) || (!ras && !cas));
        n.vid7m = !((m7 && gr_n) || (!segb && ph && !gr_n && v) || (q3 && !segb && !gr_n && v) || (ax && !segb && !gr_n && v) ||
                    (!ax && !vid7 && !q3 && !segb && !ph && !gr_n) || (cref && !ax && !h0 && !q3 && !segb && !ph && !gr_n) ||
                    (segb && !gr_n) || (gr_n && !col80_n));
        n.ldps = !((m7 && !ras && !vid7 && !q3 && !segb && !ph && !gr_n) || (!m7 && !ras && vid7 && !q3 && !segb && !ph && !gr_n) ||
                   (!ax && !q3 && segb && !ph && !gr_n) || (!ax && !q3 && !ph && gr_n) || (!ax && !q3 && ph && gr_n && !col80_n) ||
                   (cref && !ax && !h0 && !q3 && !segb && !ph && !gr_n));
        n.ck = 1;
        if (memcmp(&n, h, sizeof(n))) { *h = n; sim_mark_dirty(s, (int)(p - s->parts)); }
    }
    h->ck = (uint8_t)ck;
}
static void hal_reset(sim_t *s, part_t *p) { (void)s; memset(p->state, 0, sizeof(hal_t)); }
const part_type_t PT_A2E_HAL = { "HAL 341-0170",
    "14M:T 7M:T CREF:T H0:T VID7:T SEGB:T GR:T /CASEN:T /80COL:T GND:P /ENTMG:T LDPS:O VID7M:O PH1:O PH0:O Q3:O /PCAS:O AX:O "
    "/PRAS:O VCC:P",
    hal_eval, hal_commit, hal_reset, sizeof(hal_t), TECH_TTL };

/* ------------------------------------------------------------------------ */
/* ROMs                                                                      */
/* ------------------------------------------------------------------------ */

/* 2764 (28 pins): A0-A12, /CE (20) and /OE (22) both low enable the outputs. */
static const int rom2764_a[13] = { 10, 9, 8, 7, 6, 5, 4, 3, 25, 24, 21, 23, 2 };
static const int rom2764_d[8] = { 11, 12, 13, 15, 16, 17, 18, 19 };
static void rom2764_eval(sim_t *s, part_t *p) {
    rom_state_t *st = p->state;
    bool sel = !pin_in(s, p, 20) && !pin_in(s, p, 22);
    unsigned a = sel ? part_read_bus(s, p, rom2764_a, 13) : 0;
    part_drive_bus_cached(s, p, rom2764_d, 8, st->data ? st->data[a] : 0xFF, sel, &st->out_cache);
}
const part_type_t PT_A2E_2764 = { "2764 ROM",
    "VPP:m A12:M A7:M A6:M A5:M A4:M A3:M A2:M A1:M A0:M D0:O D1:O D2:O GND:P D3:O D4:O D5:O D6:O D7:O /CE:M A10:M /OE:M "
    "A11:M A9:M A8:M NC:m PGM:m VCC:P",
    rom2764_eval, 0, 0, sizeof(rom_state_t), TECH_NMOS };

/* 2732 (24 pins): A0-A11, /CE (18) and pin 20 (/OE) both low enable the outputs. The video ROM: pin 20 is the display window. */
static const int rom2732_a[12] = { 8, 7, 6, 5, 4, 3, 2, 1, 23, 22, 19, 21 };
static const int rom2732_d[8] = { 9, 10, 11, 13, 14, 15, 16, 17 };
static void rom2732_eval(sim_t *s, part_t *p) {
    rom_state_t *st = p->state;
    bool sel = !pin_in(s, p, 18) && !pin_in(s, p, 20);
    unsigned a = sel ? part_read_bus(s, p, rom2732_a, 12) : 0;
    part_drive_bus_cached(s, p, rom2732_d, 8, st->data ? st->data[a] : 0xFF, sel, &st->out_cache);
}
const part_type_t PT_A2E_2732 = { "2732 VIDEO",
    "A7:M A6:M A5:M A4:M A3:M A2:M A1:M A0:M D0:O D1:O D2:O GND:P D3:O D4:O D5:O D6:O D7:O /CE:M A10:M /OE:M A11:M A9:M A8:M VCC:P",
    rom2732_eval, 0, 0, sizeof(rom_state_t), TECH_NMOS };

/* ------------------------------------------------------------------------ */
/* Keyboard encoder                                                          */
/* ------------------------------------------------------------------------ */

/* 3600 PRO: not the scanning logic of the chip but what it presents once it has found a key: nine code lines (pins 6-14), the
 * strobe (16) and any-key-down (5). The code lines go straight to the address of the keyboard ROM (UE12): the line on pin 12 is
 * its A0, 13 A1, 6 A2, 7 A3, 8 A4, 9 A5, 10 A6, 11 A7 and 14 A8. The machine looks up the code of the key it types in that ROM. */
typedef struct { uint16_t code; uint8_t akd, strobe; } kb3600_t;
void apple2e_kbenc_set(part_t *p, int code, int akd, int strobe) {
    kb3600_t *t = p->state;
    if (code >= 0) t->code = (uint16_t)code;
    if (akd >= 0) t->akd = (uint8_t)akd;
    if (strobe >= 0) t->strobe = (uint8_t)strobe;
}
static void kb3600_eval(sim_t *s, part_t *p) {
    static const int pin_of_bit[9] = { 12, 13, 6, 7, 8, 9, 10, 11, 14 };
    const kb3600_t *t = p->state;
    for (int i = 0; i < 9; i++) pin_out(s, p, pin_of_bit[i], DRV_BIT((t->code >> i) & 1));
    pin_out(s, p, 16, DRV_BIT(t->strobe));
    pin_out(s, p, 5, DRV_BIT(t->akd));
}
static void kb3600_reset(sim_t *s, part_t *p) { (void)s; memset(p->state, 0, sizeof(kb3600_t)); }
const part_type_t PT_A2E_3600 = { "3600 PRO",
    "B9:O B8:O B7:O B6:O AKD:O B5:O B4:O B3:O B2:O B1:O B0:O B10:O B11:O B12:O GND:P KSTRB:O Y0:m Y1:m Y2:m Y3:m Y4:m Y5:m "
    "Y6:m Y7:m Y8:m Y9:m -12V:P /CNTL:m /SHFT:m VCC:P X9:m NC:m X7:m X6:m X5:m X4:m X3:m X2:m X1:m X0:m",
    kb3600_eval, 0, kb3600_reset, sizeof(kb3600_t), TECH_NMOS };

/* ------------------------------------------------------------------------ */
/* 74LS109 and 74LS374                                                       */
/* ------------------------------------------------------------------------ */

/* 74LS109: two J-/K flip-flops, rising edge, with /PRE and /CLR. 1: /CLR 1, J 2, /K 3, CLK 4, /PRE 5, Q 6, /Q 7; 2: /Q 9, Q 10, /PRE 11,
 * CLK 12, /K 13, J 14, /CLR 15. */
typedef struct { uint8_t q[2], ck[2]; } ls109_t;
static const int ls109_pin[2][7] = { { 1, 2, 3, 4, 5, 6, 7 }, { 15, 14, 13, 12, 11, 10, 9 } };   /* /CLR J /K CLK /PRE Q /Q */
static void ls109_eval(sim_t *s, part_t *p) {
    const ls109_t *t = p->state;
    for (int u = 0; u < 2; u++) {
        const int *g = ls109_pin[u];
        bool clr = !pin_in(s, p, g[0]), pre = !pin_in(s, p, g[4]);
        bool q = t->q[u];
        bool qo = q, qn = !q;
        if (clr && pre) qo = qn = 1;
        else if (clr) { qo = 0; qn = 1; }
        else if (pre) { qo = 1; qn = 0; }
        pin_out(s, p, g[5], DRV_BIT(qo));
        pin_out(s, p, g[6], DRV_BIT(qn));
    }
}
static void ls109_commit(sim_t *s, part_t *p) {
    ls109_t *t = p->state;
    for (int u = 0; u < 2; u++) {
        const int *g = ls109_pin[u];
        int ck = pin_in(s, p, g[3]);
        uint8_t q = t->q[u];
        bool clr = !pin_in(s, p, g[0]), pre = !pin_in(s, p, g[4]);
        if (clr || pre) { if (pre && !clr) q = 1; else if (clr && !pre) q = 0; }
        else if (ck && !t->ck[u]) {
            int j = pin_in(s, p, g[1]), kn = pin_in(s, p, g[2]);       /* /K: K = !kn */
            if (j && kn) q = 1; else if (!j && !kn) q = 0; else if (j && !kn) q = (uint8_t)!q;   /* J=1 K=1 toggles; J=1 K=0 sets */
        }
        t->ck[u] = (uint8_t)ck;
        if (q != t->q[u]) { t->q[u] = q; sim_mark_dirty(s, (int)(p - s->parts)); }
    }
}
static void ls109_reset(sim_t *s, part_t *p) { (void)s; memset(p->state, 0, sizeof(ls109_t)); }
const part_type_t PT_74LS109 = { "74LS109",
    "/1CLR:T 1J:T /1K:T 1CLK:m /1PRE:T 1Q:O /1Q:O GND:P /2Q:O 2Q:O /2PRE:T 2CLK:m /2K:T 2J:T /2CLR:T VCC:P",
    ls109_eval, ls109_commit, ls109_reset, sizeof(ls109_t), TECH_TTL };

/* 74LS374: eight D flip-flops on the rising edge of CLK (11), three-state outputs enabled by /OC (1). D on pins 3 4 7 8 13 14 17 18,
 * Q on 2 5 6 9 12 15 16 19. */
typedef struct { uint8_t q, ck; } ls374_t;
static const int ls374_d[8] = { 3, 4, 7, 8, 13, 14, 17, 18 }, ls374_q[8] = { 2, 5, 6, 9, 12, 15, 16, 19 };
static void ls374_eval(sim_t *s, part_t *p) {
    const ls374_t *t = p->state;
    bool en = !pin_in(s, p, 1);
    for (int i = 0; i < 8; i++) pin_out(s, p, ls374_q[i], en ? DRV_BIT((t->q >> i) & 1) : DRV_Z);
}
static void ls374_commit(sim_t *s, part_t *p) {
    ls374_t *t = p->state;
    int ck = pin_in(s, p, 11);
    uint8_t q = t->q;
    if (ck && !t->ck) q = (uint8_t)part_read_bus(s, p, ls374_d, 8);
    t->ck = (uint8_t)ck;
    if (q != t->q) { t->q = q; sim_mark_dirty(s, (int)(p - s->parts)); }
}
static void ls374_reset(sim_t *s, part_t *p) { (void)s; memset(p->state, 0, sizeof(ls374_t)); }
const part_type_t PT_74LS374 = { "74LS374",
    "/OC:T 1Q:O 1D:m 2D:m 2Q:O 3Q:O 3D:m 4D:m 4Q:O GND:P CLK:T 5Q:O 5D:m 6D:m 6Q:O 7Q:O 7D:m 8D:m 8Q:O VCC:P",
    ls374_eval, ls374_commit, ls374_reset, sizeof(ls374_t), TECH_TTL };
